CREATE TABLE IF NOT EXISTS "ovalo-cobranzas".motivo (
  id smallint DEFAULT nextval('"ovalo-cobranzas".motivo_id_seq'::regclass) NOT NULL,
  familia_id smallint NOT NULL,
  codigo text NOT NULL,
  descripcion text,
  PRIMARY KEY (id),
  CONSTRAINT motivo_codigo_key UNIQUE (codigo),
  CONSTRAINT "46905_49450_1_not_null" CHECK (id IS NOT NULL),
  CONSTRAINT "46905_49450_2_not_null" CHECK (familia_id IS NOT NULL),
  CONSTRAINT "46905_49450_3_not_null" CHECK (codigo IS NOT NULL)
);
ALTER TABLE "ovalo-cobranzas".motivo ADD CONSTRAINT motivo_familia_id_fkey FOREIGN KEY (familia_id) REFERENCES "ovalo-cobranzas".familia (id) ON UPDATE NO ACTION ON DELETE NO ACTION;

-- Data: motivo

CREATE TABLE IF NOT EXISTS "ovalo-cobranzas".registro_diario_correos (
  id bigint NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  estado_aviso varchar(50),
  fecha_aviso date,
  hora_aviso time without time zone,
  grupo integer,
  orden integer,
  ultima_actualizacion timestamp with time zone,
  cuotas_pagadas integer,
  cuotas_impagas integer,
  cuotas_licitadas integer,
  cuotas_vencidas integer,
  cuotas_canceladas integer,
  monto_moratoria numeric(15,2),
  monto_enriquecimiento numeric(15,2),
  monto_deuda_total numeric(15,2),
  monto_tasa_extraordinaria numeric(15,2),
  proximo_numero_cuota integer,
  desviacion integer,
  fecha_vencimiento_proxima_cuota date,
  monto_proxima_cuota numeric(15,2),
  estado integer,
  codigo_postal varchar(10),
  direccion text,
  ciudad varchar(100),
  provincia varchar(100),
  nombre text,
  telefono varchar(20),
  monto_escalonado numeric(15,2),
  monto_derecho_admision numeric(15,2),
  monto_diferimiento numeric(15,2),
  monto_sellado numeric(15,2),
  monto_otros_impuestos numeric(15,2),
  origen_envio text,
  PRIMARY KEY (id),
  CONSTRAINT registro_diario_origen_envio_check CHECK ((origen_envio = ANY (ARRAY['email'::text, 'whatsapp'::text]))),
  CONSTRAINT "46905_46913_1_not_null" CHECK (id IS NOT NULL),
  CONSTRAINT "46905_46913_2_not_null" CHECK (created_at IS NOT NULL)
);

-- Data: registro_diario_correos

CREATE OR REPLACE VIEW "ovalo-cobranzas".v_entrega_wpp AS
 SELECT e.id AS envio_id,
    c.codigo AS campania,
    c.dia_mes,
    e.fecha_envio,
    e.hora_envio,
    e.nombre,
    e.grupo,
    e.orden,
    e.destino_telefono,
    e.proveedor_msg_id AS wamid,
    e.resultado AS resultado_n8n,
    bool_or((s.status = 'sent'::text)) AS sent,
    bool_or((s.status = 'delivered'::text)) AS delivered,
    bool_or((s.status = 'read'::text)) AS read,
    bool_or((s.status = 'failed'::text)) AS failed,
    max(s.error_code) AS error_code,
    max(s.error_title) AS error_title,
        CASE
            WHEN bool_or((s.status = 'failed'::text)) THEN 'FALLO EN META'::text
            WHEN bool_or((s.status = 'read'::text)) THEN 'leido'::text
            WHEN bool_or((s.status = 'delivered'::text)) THEN 'entregado'::text
            WHEN bool_or((s.status = 'sent'::text)) THEN 'aceptado, sin entregar'::text
            ELSE 'SIN NINGUN STATUS'::text
        END AS entrega
   FROM (("ovalo-cobranzas".envio e
     JOIN "ovalo-cobranzas".campania c ON ((c.id = e.campania_id)))
     LEFT JOIN "ovalo-cobranzas".envio_status s ON ((s.wa_message_id = e.proveedor_msg_id)))
  WHERE ((e.canal_id = 1) AND (e.proveedor_msg_id ~~ 'wamid%'::text))
  GROUP BY e.id, c.codigo, c.dia_mes, e.fecha_envio, e.hora_envio, e.nombre, e.grupo, e.orden, e.destino_telefono, e.proveedor_msg_id, e.resultado;;

CREATE OR REPLACE VIEW "ovalo-cobranzas".v_resumen_envio AS
 SELECT e.corrida_id,
    cc.fecha_corrida,
    cc.ejecucion_n8n_id,
    c.id AS campania_id,
    c.codigo AS campania,
    c.dia_mes,
    m.codigo AS motivo,
    f.codigo AS familia,
    e.grupo,
    e.orden,
    max(e.nombre) AS nombre,
    max(e.email) AS email,
    max((e.telefono_norm)::text) AS telefono,
    max(e.plan) AS plan,
    max(e.modelo) AS modelo,
    max(e.localidad) AS localidad,
    max(e.provincia) AS provincia,
    max(e.cuotas_impagas) AS cuotas_impagas,
    max(e.monto_deuda_total) AS monto_deuda_total,
    max(e.status_code) AS status_code,
    max(e.resultado) FILTER (WHERE (ca.codigo = 'email'::text)) AS estado_email,
    max(e.motivo_fallo) FILTER (WHERE (ca.codigo = 'email'::text)) AS fallo_email,
    max(e.hora_envio) FILTER (WHERE (ca.codigo = 'email'::text)) AS hora_email,
    max(e.resultado) FILTER (WHERE (ca.codigo = 'whatsapp'::text)) AS estado_wpp,
    max(e.motivo_fallo) FILTER (WHERE (ca.codigo = 'whatsapp'::text)) AS fallo_wpp,
    max(e.hora_envio) FILTER (WHERE (ca.codigo = 'whatsapp'::text)) AS hora_wpp,
    count(*) AS filas_envio
   FROM ((((("ovalo-cobranzas".envio e
     JOIN "ovalo-cobranzas".campania_corrida cc ON ((cc.id = e.corrida_id)))
     JOIN "ovalo-cobranzas".campania c ON ((c.id = e.campania_id)))
     JOIN "ovalo-cobranzas".canal ca ON ((ca.id = e.canal_id)))
     LEFT JOIN "ovalo-cobranzas".motivo m ON ((m.id = c.motivo_id)))
     LEFT JOIN "ovalo-cobranzas".familia f ON ((f.id = m.familia_id)))
  GROUP BY e.corrida_id, cc.fecha_corrida, cc.ejecucion_n8n_id, c.id, c.codigo, c.dia_mes, m.codigo, f.codigo, e.grupo, e.orden;;

CREATE OR REPLACE VIEW "ovalo-cobranzas".v_efectividad_por_hora_envio AS
 SELECT (EXTRACT(hour FROM e.hora_envio))::integer AS hora_envio,
    c.codigo AS campania,
    count(*) AS enviados,
    count(m.id) AS respondidos,
    round(((100.0 * (count(m.id))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS tasa_respuesta_pct,
    round((avg(m.latencia_seg) / 60.0), 1) AS latencia_media_min
   FROM (("ovalo-cobranzas".envio e
     JOIN "ovalo-cobranzas".campania c ON ((c.id = e.campania_id)))
     LEFT JOIN "ovalo-cobranzas".mensaje_entrante m ON (((m.envio_id = e.id) AND m.es_primera_respuesta)))
  WHERE (e.resultado = 'enviado'::text)
  GROUP BY ((EXTRACT(hour FROM e.hora_envio))::integer), c.codigo
  ORDER BY ((EXTRACT(hour FROM e.hora_envio))::integer), c.codigo;;

CREATE OR REPLACE VIEW "ovalo-cobranzas".v_respuestas_por_hora AS
 SELECT (EXTRACT(hour FROM hora_recibido))::integer AS hora,
    count(*) AS mensajes,
    count(DISTINCT telefono_norm) AS personas,
    round(((100.0 * (count(*))::numeric) / NULLIF(sum(count(*)) OVER (), (0)::numeric)), 1) AS pct
   FROM "ovalo-cobranzas".mensaje_entrante
  GROUP BY ((EXTRACT(hour FROM hora_recibido))::integer)
  ORDER BY ((EXTRACT(hour FROM hora_recibido))::integer);;

CREATE OR REPLACE VIEW "ovalo-cobranzas".v_informe_diario AS
 SELECT to_char((e.fecha_envio)::timestamp with time zone, 'FMDD/FMMM/YYYY'::text) AS fecha_aviso,
    to_char((e.hora_envio)::interval, 'HH24:MI'::text) AS hora_aviso,
        CASE e.resultado
            WHEN 'enviado'::text THEN 'success'::text
            WHEN 'omitido'::text THEN ('error: '::text || COALESCE(e.motivo_fallo, 'sin telefono valido'::text))
            ELSE ('error: '::text || COALESCE(e.motivo_fallo, 'fallo de envio'::text))
        END AS estado_aviso,
    e.status_code AS estado,
    e.nombre,
    e.grupo,
    e.orden,
    e.telefono_norm AS telefono,
    e.localidad AS ciudad,
    e.provincia,
    e.cuotas_impagas,
    e.cuotas_pagadas,
    e.monto_deuda_total,
    e.monto_proxima_cuota,
    e.fecha_venc_proxima_cuota AS fecha_vencimiento_proxima_cuota,
    e.codigo_postal,
    e.direccion,
    e.email,
    e.plan,
    e.modelo,
    e.fecha_envio,
    e.resultado,
    c.dia_mes,
    c.codigo AS campania,
    ca.codigo AS canal,
    e.corrida_id,
    cc.ejecucion_n8n_id
   FROM ((("ovalo-cobranzas".envio e
     JOIN "ovalo-cobranzas".campania_corrida cc ON ((cc.id = e.corrida_id)))
     JOIN "ovalo-cobranzas".campania c ON ((c.id = e.campania_id)))
     JOIN "ovalo-cobranzas".canal ca ON ((ca.id = e.canal_id)));;
CREATE OR REPLACE FUNCTION "ovalo-cobranzas".fn_post_mensaje_entrante()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.contacto_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- El telefono del webhook es HECHO (verificado); el del padron del cliente es
  -- hipotesis. Por eso telefono_verificado nunca se degrada a false.
  UPDATE "ovalo-cobranzas".contacto_wa c
  SET ultima_vez          = GREATEST(c.ultima_vez, NEW.recibido_en),
      mensajes_recibidos  = c.mensajes_recibidos + 1,
      nombre_wa           = COALESCE(NULLIF(NEW.nombre_wa, ''), c.nombre_wa),
      wa_id               = COALESCE(NULLIF(NEW.wa_id, ''), c.wa_id),
      telefono_norm       = COALESCE(NEW.telefono_norm, c.telefono_norm),
      telefono_origen     = CASE WHEN NEW.telefono_norm IS NOT NULL
                                 THEN 'webhook_meta' ELSE c.telefono_origen END,
      telefono_verificado = c.telefono_verificado OR (NEW.telefono_norm IS NOT NULL),
      telefono_visto_en   = CASE WHEN NEW.telefono_norm IS NOT NULL
                                 THEN NEW.recibido_en ELSE c.telefono_visto_en END
  WHERE c.id = NEW.contacto_id;

  -- Vincular el plan. Solo si el perfil no tiene contacto todavia: un vinculo ya
  -- establecido NUNCA se pisa desde aca (el multi-plan lo resuelve el AI, punto 5).
  IF NEW.grupo IS NOT NULL AND NEW.orden IS NOT NULL THEN
    UPDATE "ovalo-cobranzas".ahorrista_perfil ap
    SET contacto_id = NEW.contacto_id
    WHERE ap.grupo = NEW.grupo
      AND ap.orden = NEW.orden
      AND ap.contacto_id IS NULL;
  END IF;

  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION "ovalo-cobranzas".fn_atribuir_mensaje_entrante()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_env  RECORD;
  v_tel  text;   -- text, NO varchar(10): el crudo llega con 13 digitos y se recorta despues
  v_cand smallint;
BEGIN
  v_tel := NEW.telefono_norm;
  IF v_tel IS NULL THEN
    v_tel := regexp_replace(COALESCE(NEW.telefono, NEW.wa_id, ''), '\D', '', 'g');
    v_tel := regexp_replace(v_tel, '^0+', '');
    IF length(v_tel) > 10 AND left(v_tel, 3) = '549' THEN v_tel := substr(v_tel, 4);
    ELSIF length(v_tel) > 10 AND left(v_tel, 2) = '54' THEN v_tel := substr(v_tel, 3);
    END IF;
    IF length(v_tel) > 10 AND left(v_tel, 1) = '9' THEN v_tel := substr(v_tel, 2); END IF;
    IF length(v_tel) > 10 THEN v_tel := right(v_tel, 10); END IF;
    IF length(v_tel) <> 10 THEN v_tel := NULL; END IF;
    NEW.telefono_norm := v_tel;
  END IF;

  -- Cuantos planes distintos comparten este telefono segun el historial de envios.
  -- n8n manda 0 fijo, asi que el trigger es la unica fuente real de este dato.
  IF NEW.telefono_norm IS NULL THEN
    v_cand := 0;
  ELSE
    SELECT count(DISTINCT (e.grupo, e.orden))::smallint INTO v_cand
    FROM "ovalo-cobranzas".envio e
    WHERE e.telefono_norm = NEW.telefono_norm
      AND e.grupo IS NOT NULL AND e.orden IS NOT NULL;
  END IF;
  NEW.perfiles_candidatos := v_cand;

  IF NEW.contexto_wamid IS NOT NULL AND NEW.contexto_wamid <> '' THEN
    SELECT e.id, e.campania_id, e.corrida_id, e.enviado_en, e.grupo, e.orden INTO v_env
    FROM "ovalo-cobranzas".envio e
    WHERE e.proveedor_msg_id = NEW.contexto_wamid
    ORDER BY e.enviado_en DESC
    LIMIT 1;
    IF FOUND THEN NEW.atribucion_metodo := 'contexto_wamid'; END IF;
  END IF;

  IF NEW.atribucion_metodo IS NULL AND NEW.telefono_norm IS NOT NULL THEN
    SELECT e.id, e.campania_id, e.corrida_id, e.enviado_en, e.grupo, e.orden INTO v_env
    FROM "ovalo-cobranzas".envio e
    WHERE e.telefono_norm = NEW.telefono_norm
      AND e.resultado = 'enviado'
      AND e.enviado_en <= NEW.recibido_en
    ORDER BY e.enviado_en DESC
    LIMIT 1;
    IF FOUND THEN NEW.atribucion_metodo := 'ultimo_envio_telefono'; END IF;
  END IF;

  IF NEW.atribucion_metodo IS NULL THEN
    NEW.atribucion_metodo := 'sin_atribucion';
  ELSE
    NEW.envio_id     := v_env.id;
    NEW.campania_id  := v_env.campania_id;
    NEW.corrida_id   := v_env.corrida_id;
    NEW.latencia_seg := GREATEST(0, EXTRACT(EPOCH FROM (NEW.recibido_en - v_env.enviado_en))::integer);
    NEW.es_primera_respuesta := NOT EXISTS (
      SELECT 1 FROM "ovalo-cobranzas".mensaje_entrante m WHERE m.envio_id = v_env.id);

    -- grupo/orden solo cuando la identificacion es inequivoca:
    --   * contexto_wamid  -> el wamid apunta a UN envio, sirve aunque el telefono tenga N planes
    --   * por telefono    -> solo si ese telefono tiene un unico plan
    -- El caso multi-plan sin boton queda NULL a proposito: lo resuelve despues el
    -- conversacional, cuando el AI identifica el plan. Un valor adivinado seria peor que NULL.
    IF NEW.grupo IS NULL AND NEW.orden IS NULL
       AND (NEW.atribucion_metodo = 'contexto_wamid' OR v_cand <= 1) THEN
      NEW.grupo := v_env.grupo;
      NEW.orden := v_env.orden;
    END IF;
  END IF;

  -- ==========================================================================
  -- Meta 2026 - identidad BSUID (agregado 2026-08-19)
  -- ==========================================================================
  -- Resolver o crear el contacto de WhatsApp. El BSUID es la clave natural y
  -- solo llega en el entrante: el acuse del saliente NO lo devuelve.
  IF NEW.bsuid IS NOT NULL AND NEW.bsuid <> '' THEN
       wa_id, nombre_wa, origen, metodo_identificacion)
    VALUES
      (NEW.bsuid,
       NEW.telefono_norm,
       CASE WHEN NEW.telefono_norm IS NOT NULL THEN 'webhook_meta' END,
       NEW.telefono_norm IS NOT NULL,
       CASE WHEN NEW.telefono_norm IS NOT NULL THEN NEW.recibido_en END,
       NULLIF(NEW.wa_id, ''),
       NULLIF(NEW.nombre_wa, ''),
       'inbound',
       'bsuid')
    ON CONFLICT (bsuid) DO NOTHING;

    SELECT c.id INTO NEW.contacto_id
    FROM "ovalo-cobranzas".contacto_wa c
    WHERE c.bsuid = NEW.bsuid;
  END IF;

  -- Cerrar el eslabon entrante -> perfil, que hasta hoy quedaba siempre NULL.
  -- Solo cuando grupo/orden ya se resolvieron de forma inequivoca (bloque de arriba).
  IF NEW.ahorrista_id IS NULL AND NEW.grupo IS NOT NULL AND NEW.orden IS NOT NULL THEN
    SELECT ap.id INTO NEW.ahorrista_id
    FROM "ovalo-cobranzas".ahorrista_perfil ap
    WHERE ap.grupo = NEW.grupo AND ap.orden = NEW.orden;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE TRIGGER update_ahorrista_perfil_updated_at BEFORE UPDATE ON "ovalo-cobranzas".ahorrista_perfil FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trg_atribuir_mensaje_entrante BEFORE INSERT ON "ovalo-cobranzas".mensaje_entrante FOR EACH ROW EXECUTE FUNCTION "ovalo-cobranzas".fn_atribuir_mensaje_entrante();

CREATE TRIGGER trg_post_mensaje_entrante AFTER INSERT ON "ovalo-cobranzas".mensaje_entrante FOR EACH ROW EXECUTE FUNCTION "ovalo-cobranzas".fn_post_mensaje_entrante();


